  }
  html{scroll-padding-top:5rem;}           /* sticky 타이머가 포커스를 가리지 않게 (2.4.11) */
  body{margin:0;font:16px/1.5 system-ui,sans-serif;color:var(--text);background:#fff;}
  main{max-width:32rem;margin:0 auto;padding:0 1rem 3rem;}
  h1{font-size:1.5rem;margin:1.25rem 0 .5rem;}
  .timer{position:sticky;top:0;z-index:10;display:flex;flex-wrap:wrap;gap:.5rem;
    justify-content:space-between;align-items:center;padding:.5rem 1rem;
