  input[type=text],input[type=email],input[type=tel]{
    box-sizing:border-box;width:100%;min-height:44px;padding:.5rem .75rem;
    font:inherit;color:var(--text);background:#fff;
    border:1px solid var(--border);border-radius:4px;}
  input[aria-invalid="true"]{border:2px solid var(--error);}
  :focus-visible{outline:3px solid var(--brand-ink);outline-offset:2px;}
  .hint{margin:.25rem 0 0;font-size:.875rem;color:var(--muted);}
  .field-err{margin:.25rem 0 0;font-size:.875rem;font-weight:600;color:var(--error);}
  .field-err:empty{display:none;}
  fieldset{border:0;padding:0;margin:0 0 .5rem;}
