             spellcheck="false" required aria-describedby="captcha-hint captcha-err">
      <p id="captcha-err" class="field-err"></p>
    </div>

    <div class="field">
      <label class="check">
        <input type="checkbox" name="news" value="email" aria-describedby="news-hint">
        <span><span class="opt">(선택)</span> 이벤트·혜택 소식을 이메일로 받기</span>
      </label>
      <p id="news-hint" class="hint">동의하지 않아도 예매할 수 있으며, 언제든 수신을 거부할 수 있습니다.</p>
