    <button type="button" class="pay" id="warn-extend" autofocus>5분 연장하기</button>
    <button type="button" class="btn-sec" id="warn-continue">계속 입력</button>
  </div>
</dialog>

<dialog id="expired-dialog" aria-labelledby="xd-title" aria-describedby="xd-desc">
