    <button type="button" class="btn-sec" id="xd-close">닫기</button>
  </div>
</dialog>

<script>
(() => {
  /* ===== 설정 (가정한 비즈니스 결정) ===== */
  const HOLD_SECONDS   = 600; // 2분에서 10분으로 상향
  const EXTEND_SECONDS = 300; // 1회 연장 시간
  const MAX_EXTENSIONS = 10;  // WCAG 2.2.1: 최소 10회 연장 허용
  const WARN_AT        = 60;  // 만료 60초 전 경고 (기준은 20초 이상)

  const $ = id => document.getElementById(id);
  const form = $('order'), pay = $('pay'), live = $('live');
  const tEl = $('t'), bar = $('timer-bar'), extendInline = $('extend-inline');
  const warnDlg = $('warn-dialog'), expDlg = $('expired-dialog');
  const email = $('email'), echo = $('email-echo');

  let deadline = Date.now() + HOLD_SECONDS * 1000;
  let extensions = 0, expired = false, warned = false, said5 = false, submitting = false;
  let returnFocus = null;

  const fmt = s => `${Math.floor(s / 60)}:${String(s % 60).padStart(2, '0')}`;
  const left = () => Math.max(0, Math.ceil((deadline - Date.now()) / 1000));
  function announce(msg) { live.textContent = ''; setTimeout(() => { live.textContent = msg; }, 50); }

  /* ===== 입력값 보존 (카드 정보 제외) ===== */
  const SAVE = ['name', 'email', 'phone'];
  function saveBuyer() {
    try { sessionStorage.setItem('sb-buyer', JSON.stringify(Object.fromEntries(SAVE.map(k => [k, $(k).value])))); } catch (e) {}
  }
  try {
    const saved = JSON.parse(sessionStorage.getItem('sb-buyer') || 'null');
    if (saved) SAVE.forEach(k => { if (saved[k]) $(k).value = saved[k]; });
  } catch (e) {}
  SAVE.forEach(k => $(k).addEventListener('input', saveBuyer));

  /* ===== 타이머 ===== */
  function openDialog(d) {
    if (d.open) return;
    if (!document.querySelector('dialog[open]')) returnFocus = document.activeElement;
    d.showModal();
  }
  [warnDlg, expDlg].forEach(d => d.addEventListener('close', () => {
    if (!document.querySelector('dialog[open]') && returnFocus && document.contains(returnFocus)) returnFocus.focus();
  }));

  function tick() {
    if (expired) return;
    const s = left();
    tEl.textContent = fmt(s);
    bar.classList.toggle('low', s <= WARN_AT);
