  /* ===== 이메일 오타 제안 ===== */
  const DOMAINS = ['gmail.com','naver.com','daum.net','hanmail.net','kakao.com','nate.com',
    'icloud.com','outlook.com','hotmail.com','yahoo.com','gmx.de','web.de','t-online.de','orange.fr','libero.it'];
  function lev(a, b) {
    const d = Array.from({ length: a.length + 1 }, (_, i) => [i, ...Array(b.length).fill(0)]);
    for (let j = 1; j <= b.length; j++) d[0][j] = j;
    for (let i = 1; i <= a.length; i++)
      for (let j = 1; j <= b.length; j++)
        d[i][j] = Math.min(d[i-1][j] + 1, d[i][j-1] + 1, d[i-1][j-1] + (a[i-1] === b[j-1] ? 0 : 1));
    return d[a.length][b.length];
  }
  function suggestion(v) {
    const at = v.lastIndexOf('@');
    if (at < 1) return null;
    const dom = v.slice(at + 1).toLowerCase();
    if (!dom || DOMAINS.includes(dom)) return null;
    let best = null, bd = 3;
    for (const c of DOMAINS) { const x = lev(dom, c); if (x < bd) { bd = x; best = c; } }
    return best ? v.slice(0, at + 1) + best : null;
  }
