  const luhn = d => {
    let sum = 0, alt = false;
    for (let i = d.length - 1; i >= 0; i--) {
      let n = +d[i];
      if (alt) { n *= 2; if (n > 9) n -= 9; }
      sum += n; alt = !alt;
    }
    return sum % 10 === 0;
  };
  const rules = {
    name:  v => v ? '' : '이름을 입력해 주세요.',
    email: v => !v ? '이메일을 입력해 주세요.'
