    phone: v => !v || /^\+?[\d\s-]{7,20}$/.test(v) ? '' : '숫자, 공백, +, - 만 사용해 주세요.',
    card:  v => {
      const d = v.replace(/\D/g, '');
      if (!d) return '카드 번호를 입력해 주세요.';
      return d.length >= 13 && d.length <= 19 && luhn(d) ? '' : '카드 번호를 다시 확인해 주세요. (숫자 13~19자리)';
    },
    exp:   v => {
