      return new Date(2000 + +m[2], +m[1], 1) > new Date() ? '' : '유효기간이 지난 카드입니다.';
    },
    cvc:   v => /^\d{3,4}$/.test(v) ? '' : 'CVC 숫자 3~4자리를 입력해 주세요.',
    captcha: v => v ? '' : '보안문자를 입력해 주세요.'
